steps.body:
A function can declare several type parameters, separated by commas. Each one is inferred on its own, from the argument where it appears:

```typescript
function pair<A, B>(a: A, b: B): [A, B] {
  return [a, b];
}

const entry = pair("mug", 3);
//    ^? const entry: [string, number]
console.log(entry.join(" x ")); // mug x 3
```

Inference needs a value to look at. An empty array `[]` has no elements, so TypeScript gives it the type `never[]`, an array that can never hold anything. When an argument can't tell TypeScript the type, write the type arguments yourself, in angle brackets after the function's name: `pair<string, number>("mug", 3)`.

Type arguments you write win over inference, and the checker holds each argument to them:

```typescript error
function pair<A, B>(a: A, b: B): [A, B] {
  return [a, b];
}

const entry = pair<string, number>("mug", "3");
console.log(entry.join(" x "));
```

examples.code:
function pair<A, B>(a: A, b: B): [A, B] {
  return [a, b];
}

const stock = pair("Mug", 4);
//    ^? const stock: [string, number]
const flag = pair(true, ["beta", "dark-mode"]);
//    ^? const flag: [boolean, string[]]

const [item, count] = stock;
console.log(`${item}: ${count} left`);
console.log(`Enabled: ${flag[0]}, groups: ${flag[1].join(", ")}`);

function zip<A, B>(xs: readonly A[], ys: readonly B[]): [A, B][] {
  const pairs: [A, B][] = [];
  const length = Math.min(xs.length, ys.length);
  for (let i = 0; i < length; i++) {
    const x = xs[i];
    const y = ys[i];
    if (x !== undefined && y !== undefined) pairs.push([x, y]);
  }
  return pairs;
}

const names = ["Ana", "Ben", "Caro"];
const scores = [91, 78];

const results = zip(names, scores);
//    ^? const results: [string, number][]
for (const [name, score] of results) {
  console.log(`${name}: ${score}`);
}
console.log(`${results.length} pairs`);

function createStore<T>(initial: T) {
  let state = initial;
  return {
    get: () => state,
    set: (next: T) => {
      state = next;
    },
  };
}

const cart = createStore([]);
cart.get().push("milk");
console.log(cart.get().join(", "));

examples.explanation:
`T` is inferred from `[]`, and an empty array is `never[]`, so this store can only ever hold an array of nothing, and pushing `"milk"` is rejected. Nothing in the call says what the cart should hold, so say it with a type argument:

```typescript
function createStore<T>(initial: T) {
  let state = initial;
  return {
    get: () => state,
    set: (next: T) => {
      state = next;
    },
  };
}

const cart = createStore<string[]>([]);
cart.get().push("milk");
cart.set([...cart.get(), "eggs"]);
console.log(cart.get().join(", ")); // milk, eggs
```

With `T` set to `string[]`, `get` returns a `string[]` and `set` takes one.

