practice.solution:
export function chunk<T>(xs: readonly T[], size: number): T[][] {
  const groups: T[][] = [];
  for (let i = 0; i < xs.length; i += size) {
    groups.push(xs.slice(i, i + size));
  }
  return groups;
}

const seats = [1, 2, 3, 4, 5];
const guests = ["Ana", "Ben", "Caro", "Dev", "Eli"];

console.log(JSON.stringify(chunk(seats, 2)));
console.log(JSON.stringify(chunk(guests, 3)));

steps.body:
A callback's type can use type parameters too. In `fn: (x: T) => R`, `T` is fixed by the array you pass, and `R` is whatever your callback returns, so the caller decides the result type:

```typescript
function mapArray<T, R>(xs: readonly T[], fn: (x: T) => R): R[] {
  const out: R[] = [];
  for (const x of xs) out.push(fn(x));
  return out;
}

const lengths = mapArray(["ts", "node"], (s) => s.length);
//    ^? const lengths: number[]
console.log(lengths.join(", ")); // 2, 4
```

You don't annotate `s`. `T` is already `string`, from the array, so the callback's parameter gets its type from there, just as a callback you pass to `map` does. That's no coincidence: the built-in array methods are generic functions written the same way. Leaving out an optional last parameter, `map` is declared as `map<U>(callbackfn: (value: T, index: number, array: T[]) => U): U[]`, where `T` is the array's element type and `U` is what your callback returns.

examples.code:
function mapArray<T, R>(xs: readonly T[], fn: (x: T) => R): R[] {
  const out: R[] = [];
  for (const x of xs) {
    out.push(fn(x));
  }
  return out;
}

const pricesCents = [1299, 450, 5000];

const labels = mapArray(pricesCents, (cents) => `$${(cents / 100).toFixed(2)}`);
//    ^? const labels: string[]
const pricey = mapArray(pricesCents, (cents) => cents >= 1000);
//    ^? const pricey: boolean[]

console.log(labels.join(", "));
console.log(pricey.join(", "));

type Order = {
  id: string;
  status: "paid" | "shipped" | "pending";
  totalCents: number;
};

function groupBy<T>(xs: readonly T[], key: (x: T) => string): Record<string, T[]> {
  const groups: Record<string, T[]> = {};
  for (const x of xs) {
    (groups[key(x)] ??= []).push(x);
  }
  return groups;
}

const orders: Order[] = [
  { id: "o1", status: "paid", totalCents: 1299 },
  { id: "o2", status: "shipped", totalCents: 450 },
  { id: "o3", status: "paid", totalCents: 5000 },
];

const byStatus = groupBy(orders, (o) => o.status);
//    ^? const byStatus: Record<string, Order[]>
for (const [status, group] of Object.entries(byStatus)) {
  console.log(`${status}: ${group.map((o) => o.id).join(", ")}`);
}

type Order = {
  id: string;
  status: "paid" | "shipped" | "pending";
  totalCents: number;
};

const orders: Order[] = [
  { id: "o1", status: "paid", totalCents: 1299 },
  { id: "o2", status: "shipped", totalCents: 450 },
  { id: "o3", status: "paid", totalCents: 5000 },
];

const byStatus = Object.groupBy(orders, (o) => o.status);
//    ^? const byStatus: Partial<Record<"paid" | "pending" | "shipped", Order[]>>
console.log(`Paid: ${byStatus.paid?.length ?? 0}`);
console.log(`Pending: ${byStatus.pending?.length ?? 0}`);

const bySize = Map.groupBy(orders, (o) => (o.totalCents >= 1000 ? "large" : "small"));
//    ^? const bySize: Map<"large" | "small", Order[]>
for (const [size, group] of bySize) {
  console.log(`${size}: ${group.map((o) => o.id).join(", ")}`);
}

