practice.solution:
type Product = { name: string; category: string };

export function countBy<T>(
  xs: readonly T[],
  key: (x: T) => string,
): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const x of xs) {
    const k = key(x);
    counts[k] = (counts[k] ?? 0) + 1;
  }
  return counts;
}

const products: Product[] = [
  { name: "Mug", category: "kitchen" },
  { name: "Stapler", category: "office" },
  { name: "Kettle", category: "kitchen" },
  { name: "Trowel", category: "garden" },
  { name: "Notebook", category: "office" },
  { name: "Teapot", category: "kitchen" },
];

const counts = countBy(products, (p) => p.category);
const sorted = Object.entries(counts).toSorted(([a], [b]) => a.localeCompare(b));
for (const [category, n] of sorted) {
  console.log(`${category}: ${n}`);
}
